# enumerate exact cover of test by 2x2-based tiles of size 3 or 4
occ={(0,1),(0,2),(0,4),(0,5)}|{(1,c) for c in range(6)}|{(2,c) for c in (1,2,4)}|{(3,c) for c in (2,3,4)}
from collections import defaultdict
opts=[]
for r in range(6):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for mask in range(1,16):
   cells={x for i,x in enumerate(sorted(block)) if mask>>i&1}
   if cells <= occ and len(cells) in (3,4): opts.append((cells,mask,r,c))
def covers(rem):
 if not rem: return [[]]
 p=min(rem)
 out=[]
 for tile,*_ in opts:
  if p in tile and tile<=rem:
   out += [[tile]+x for x in covers(rem-tile)]
 return out
sols=covers(occ)
len(sols), [list(map(len,s)) for s in sols[:5]]
